-- Link all occurrences generated by a recurring booking to one series.
alter table public.appointments
  add column if not exists recurrence_series_id uuid;

-- Older recurring bookings were inserted in one atomic INSERT. Their shared
-- created_at plus customer/service/professional identity lets us safely group
-- those batches without matching unrelated appointments by weekday alone.
with recurring_batches as (
  select
    barbershop_id,
    created_at,
    client_id,
    manual_name,
    manual_phone,
    manual_email,
    service_id,
    professional_id,
    gen_random_uuid() as series_id
  from public.appointments
  where recurrence_series_id is null
  group by
    barbershop_id,
    created_at,
    client_id,
    manual_name,
    manual_phone,
    manual_email,
    service_id,
    professional_id
  having count(*) > 1
)
update public.appointments as appointment
set recurrence_series_id = batch.series_id
from recurring_batches as batch
where appointment.recurrence_series_id is null
  and appointment.barbershop_id = batch.barbershop_id
  and appointment.created_at = batch.created_at
  and appointment.client_id is not distinct from batch.client_id
  and appointment.manual_name is not distinct from batch.manual_name
  and appointment.manual_phone is not distinct from batch.manual_phone
  and appointment.manual_email is not distinct from batch.manual_email
  and appointment.service_id is not distinct from batch.service_id
  and appointment.professional_id is not distinct from batch.professional_id;

create index if not exists appointments_recurrence_series_idx
  on public.appointments (barbershop_id, recurrence_series_id, date_hour)
  where recurrence_series_id is not null;

comment on column public.appointments.recurrence_series_id is
  'Shared identifier for appointments created together as one recurring booking series.';
